(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sk"] = {"ui":{"skip":"Preskočiť na obsah","back":"← Späť na AI-gile","lang.button":"Jazyk: {name}","lang.dialog":"Vyber jazyk","lang.search":"Hľadať jazyky","lang.none":"Žiadny jazyk nezodpovedá","lang.notYet":"{name} ešte nie je preložený","theme.aria":"Prepnúť medzi svetlou a tmavou témou","theme.toLight":"Prepnúť na svetlú tému","theme.toDark":"Prepnúť na tmavú tému","words.underline":"Podčiarknuť tieto slová na stránke","words.underlineHelp":"Prejdi myšou nad bodkovane podčiarknuté slovo alebo naň ťukni a uvidíš, čo znamená.","index.title":"AI-gile: tvoj AI vývojársky tím na jednej tabuli","index.description":"AI-gile je kanban tabuľa pre tímy AI programátorov. Pracujú, kým spíš; ty dostaneš jednu krátku kôpku vecí na rozhodnutie, otestovanie a schválenie.","hero.logoAlt":"Ikona tabule AI-gile","hero.h1.html":"Tvoj AI vývojársky tím na jednej&nbsp;tabuli.","hero.alpha":"🐣 Uzavretá pre-alfa","hero.alphaTitle":"Skorá a nedokončená verzia: vďaka, že ju skúšaš!","hero.lede":"Stavajú, kým spíš. Ráno ťa čaká jedna krátka kôpka: pár otázok, pár vecí na otestovanie, jeden-dva fialové diamanty. Klikneš, schválíš a vrátiš sa ku káve.","dl.windows":"Aplikácia pre Windows","dl.browser":"Spustiť v prehliadači","dl.soon":"Čoskoro","dl.notify":"🔔 Daj mi vedieť, keď sa otvorí","dl.notifySmall":"Alfa alebo beta","hero.secondary":"Agilne, ale tím nikdy nepotrebuje ranný stand-up s kávou. (Stand-upy aj tak robia.)","pitch.h2":"AI-gile v toľkých slovách, koľko chceš","pitch.lede":"Vyber dĺžku, od jedného slova po 144. Každá dĺžka je samostatný popis napísaný práve pre ňu. Potiahni posuvník alebo použi šípky.","pitch.rangeLabel":"Dĺžka v slovách","pitch.dice":"🎲 iná verzia","pitch.words.one":"{n} slovo","pitch.words.other":"{n} slov","pitch.letters.one":"{n} písmeno","pitch.letters.other":"{n} písmen","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakov","count.line.html.one":"{n} karta je práve na tabuli","count.line.html.other":"{n} kariet je práve na tabuli","features.aria":"Čo robí","f.pile.h":"Jedna kôpka pre teba","f.pile.html":"<b>Pre teba</b> obsahuje všetko, čo čaká na teba, naprieč všetkými projektmi: otázky, veci na otestovanie, úlohy, ktoré zvládne len človek. Tvoj rad ti povie, čo je na rade a koľko to potrvá.","f.sleep.h":"Tímy, ktoré pracujú, kým spíš","f.sleep.p":"Každý projekt má vedúceho a tím AI agentov. Napíš komentár ku karte a tím sa zobudí, odvedie prácu a vráti ti ju s krokmi, ktoré zvládne aj unavený človek.","f.tester.h":"Najprv kontroluje AI tester","f.tester.p":"Skôr než sa čokoľvek dostane k tebe, tester prejde kroky v kópii aplikácie a ukáže, čo videl, so snímkou obrazovky. Prelistuj tie, čo prešli, a schváľ jedným klikom.","f.proof.h":"Dôkazy, nie sľuby","f.proof.p":"Každé odovzdanie ukazuje, čo sa zmenilo: súbory, rozdiely, snímky obrazovky. Nemusíš otvárať každú aplikáciu, aby si zistil, či je hotovo.","f.chat.h":"Chat so svojimi vedúcimi","f.chat.p":"Lišta ako na Discorde: jedna ikona na projekt, fialové diamanty pri tom, čo potrebuje teba. Napíš vedúcemu nápad; premení ho na karty a plán s tlačidlom ✅ Ísť na to.","f.tidy.h":"Upratuje si po sebe","f.tidy.p":"Súvisiace karty sa zlúčia, zmätené názvy sa opravia a kontrola tokenov udržiava kód štíhly. Menej vecí na prepínanie, menej na premýšľanie.","f.private.h":"Tvoje, na tvojom počítači","f.private.li1":"Tabuľa beží na tvojom vlastnom stroji a odpovedá len tebe.","f.private.li2":"Súkromné správy medzi ľuďmi sú šifrované end-to-end.","f.private.li3":"Žiadne účty, žiadne sledovače, žiadne cookies.","f.lang.h":"Vo tvojom jazyku","f.lang.p":"Vyše 120 jazykov, od holandčiny, walesčiny a japončiny až po pirátčinu, Yodu a klingončinu, s rýchlym prepnutím späť do angličtiny pre vývojárske slová.","f.service.h":"Od nápadu k skutočnej službe","f.service.p":"Postavil si s AI niečo, čo ľudia teraz používajú? Označ to ako službu a board ti pomôže dobre ju prevádzkovať: kontroly dostupnosti, verejná stránka stavu, incidenty s rozborom, zmeny, ktoré potrebujú Go, zálohy kontrolované každý deň. Pomocník ťa naučí každý krok počas práce.","tl.aria":"Časová os od prvého rozhovoru po plán","tl.h2":"Od prvého rozhovoru po to, čo príde","tl.lede":"Skutočné dátumy a časy vo tvojom časovom pásme. Po dnešku je to plán, bez sľubovaných dátumov.","tl.today":"Dnes","tl.planned":"plánované","tl.cards.one":"{n} karta","tl.cards.other":"{n} kariet","join.h2":"Pridaj sa","join.lede":"AI-gile stavia jeden malý človek a veľa trpezlivých agentov. Zatiaľ je súkromné, v uzavretej alfe s priateľmi. Chceš si ho vyskúšať, keď sa otvorí?","join.btn":"Prejaviť záujem","join.small":"Napíšeme ti e-mail, nič iné","footer.tag":"AI-gile. Žiadne sledovače, žiadne cookies, žiadna stand-up káva.","footer.licence":"Podniková licencia","footer.status":"Stav","footer.privacy":"Čo uchovávame","form.sending":"Odosiela sa…","form.failed":"Nevyšlo to: skús to neskôr.","form.offline":"AI-gile sa nepodarilo kontaktovať: skús to neskôr.","form.keep":"Použijeme to len na to, aby sme ti odpovedali, potom to zmažeme. Žiadne sledovače, žiadne cookies.","form.keepLink":"Čo uchovávame","interest.title":"AI-gile: daj mi vedieť, keď sa otvorí alfa","interest.description":"Nechaj nám e-mail a dáme ti vedieť, keď sa otvorí uzavretá alfa alebo beta AI-gile.","interest.h1":"🔔 Daj mi vedieť, keď sa otvorí","interest.lede":"AI-gile je v uzavretej pre-alfe. Nechaj nám e-mail a napíšeme ti raz, keď bude pre teba miesto.","interest.email":"Tvoj e-mail","interest.which":"Ktorý test?","interest.alpha":"Uzavretá alfa: skorá, drsná, veľa zmien","interest.beta":"Beta: stabilnejšia, neskôr","interest.both":"Ktorýkoľvek, podľa toho, čo bude skôr","interest.submit":"Zapísať ma do zoznamu","interest.thanks":"Vďaka! Si v zozname.","licence.title":"AI-gile: podniková licencia","licence.description":"Používaš AI-gile vo svojej firme? Požiadaj o bezplatnú podnikovú licenciu.","licence.h1":"📜 Podniková licencia","licence.lede":"Používaš AI-gile v práci? Povedz nám, kto si a čo robíš. Ak to robí svet lepším, licencia je zadarmo.","licence.company":"Firma","licence.website":"Web","licence.what":"Čo robíš","licence.how":"Ako to pomáha svetu","licence.email":"E-mail","licence.submit":"Požiadať","licence.thanks":"Vďaka! Odpovieme e-mailom.","status.title":"Stav AI-gile","status.h1":"Stav AI-gile","status.quiet":"Všetko pokojné","status.intro":"Funguje AI-gile práve teraz? Táto stránka každých 5 minút kontroluje web, zdieľanie tabúľ, hovory a sťahovanie.","status.up":"Funguje (odpoveď za {ms} ms)","status.slow":"Bez odpovede pri poslednej kontrole, skúšam znova","status.down":"Nefunguje: bez odpovede pri posledných dvoch kontrolách","status.svc.web":"Web","status.svc.web.offers":"Táto stránka: čo je AI-gile a formulár na prejavenie záujmu","status.svc.boards":"Zdieľanie tabúľ","status.svc.boards.offers":"Verejné tabule, správy medzi priateľmi a pozvánky","status.svc.calls":"Hovory","status.svc.calls.offers":"Hlas, video a zdieľanie obrazovky v AI-gile","status.svc.download":"Sťahovanie","status.svc.download.offers":"Inštalátor pre Windows a odkazy na pozvánky","status.checking":"Kontroluje sa…","status.offline":"Služba stavu je teraz nedostupná (skúšam znova)","status.updated":"aktualizované {ago}","status.justNow":"práve teraz","status.min":"pred {n} min","status.hours":"pred {n} h","status.days":"pred {n} d","privacy.title":"AI-gile: čo uchovávame","privacy.h1":"Čo uchovávame","privacy.lede":"Stručne: len to, čo nám pošleš, a nie nadlho.","privacy.only":"Len to, čo nám pošleš: to, čo napíšeš do formulára, napríklad svoj e-mail. Nič iné o tebe.","privacy.sealed":"Je to zapečatené, takže náš server to nedokáže prečítať: v tvojom prehliadači ešte pred odoslaním (v staršom prehliadači hneď po doručení). Otvoriť to vie len naša vlastná tabuľa.","privacy.server":"Zo servera sa to zmaže hneď, ako to dorazí na našu tabuľu. Čokoľvek, čo tam zostane aj po 30 dňoch, sa aj tak zmaže.","privacy.board":"Na našej tabuli to necháme len dovtedy, kým ti neodpovieme, potom to zmažeme aj tam.","privacy.none":"Žiadne sledovače, žiadne cookies, žiadna analytika.","privacy.local":"Tvoj jazyk a voľba svetlej či tmavej témy zostávajú v tvojom prehliadači. Nikdy sa nám neposielajú.","privacy.ask":"Chceš, aby to zmizlo skôr? Odpovedz na náš e-mail a napíš nám to.","live.h2":"Sledujte, ako sa to stavia, naživo","live.caption":"Každá karta je skrytá: vidíte tvar práce, nie slová.","live.watching.one":"naživo: sleduje {n}","live.watching.other":"naživo: sledujú {n}","live.last.now":"Posledná karta presunutá práve teraz","live.last.min.one":"Posledná karta presunutá pred {n} minútou","live.last.min.other":"Posledná karta presunutá pred {n} minútami","live.last.hour.one":"Posledná karta presunutá pred {n} hodinou","live.last.hour.other":"Posledná karta presunutá pred {n} hodinami","live.last.day.one":"Posledná karta presunutá pred {n} dňom","live.last.day.other":"Posledná karta presunutá pred {n} dňami","live.offline":"Živá tabuľa si dáva pauzu. Skúste to čoskoro znova.","live.cols":"Backlog|Na urobenie|Rozrobené|Tím kontroluje|Čaká na tvoj test|Pre tím|Hotovo","pitch.words.few":"{n} slová","pitch.words.many":"{n} slova","pitch.letters.few":"{n} písmená","pitch.letters.many":"{n} písmena","pitch.chars.few":"{n} znaky","pitch.chars.many":"{n} znaku","count.line.html.few":"{n} karty sú práve na tabuli","count.line.html.many":"{n} karty je práve na tabuli","tl.cards.few":"{n} karty","tl.cards.many":"{n} karty","live.last.min.few":"Posledná karta presunutá pred {n} minútami","live.last.min.many":"Posledná karta presunutá pred {n} minúty","live.last.hour.few":"Posledná karta presunutá pred {n} hodinami","live.last.hour.many":"Posledná karta presunutá pred {n} hodiny","live.last.day.few":"Posledná karta presunutá pred {n} dňami","live.last.day.many":"Posledná karta presunutá pred {n} dňa"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegované."]},{"n":2,"texts":["Robotický kanban.","Agenti, usporiadaní.","Nápady hotovo."]},{"n":3,"texts":["Kanban pre robotov.","Z nápadov funkcie.","Bezplatný kanban agentov."]},{"n":5,"texts":["Kanban tabuľa, ktorú vedú agenti.","Ty píšeš karty. Agenti staviajú.","Zadarmo, lokálne, testované, trochu bláznivé."]},{"n":8,"texts":["Bezplatná kanban tabuľa, na ktorej pracujú AI agenti.","Napíš nápad. Agenti ho postavia. Ty ho schváliš.","Agilita pre jedného človeka a veľa trpezlivých robotov."]},{"n":13,"texts":["Kanban tabuľa na tvojom počítači, kde si karty preberajú AI agenti a pracujú na nich.","Napíš nápad. Tím agentov ho postaví. Tester ho skontroluje. Ty povieš áno.","Zadarmo, bez účtov a sledovačov: tabuľa, zopár robotov a ty ako šéf."]},{"n":21,"texts":["AI-gile je kanban tabuľa na prácu s AI agentmi, ktorí programujú. Oni preberajú karty a ty ich testuješ a schvaľuješ.","Každý projekt dostane vedúceho a tím AI agentov. Napíš komentár k ľubovoľnej karte a tím sa pustí do práce.","Bezplatná osobná tabuľa úloh, ktorá beží na tvojom vlastnom počítači. Pracujú na nej roboti. Povedať áno môžeš len ty."]},{"n":34,"texts":["Nápady dáš na tabuľu. Tím AI agentov ich premení na fungujúce funkcie, otestuje ich a vráti ti ich s krokmi na vyskúšanie. Nič nie je hotové, kým to nepovieš ty.","AI-gile je domáca kanban tabuľa, ktorú Rich postavil s veľkou pomocou agentov, ktorých dnes sama riadi. Je zadarmo, beží na tvojom počítači a zdieľa sa s priateľmi, nepredáva sa.","Predstav si obyčajnú kanban tabuľu so stĺpcami od Backlogu po Hotovo, len karty preberajú AI agenti. Hlásia pokrok, pýtajú sa, keď uviaznu, a vždy počkajú na tvoj súhlas."]},{"n":55,"texts":["AI-gile je kanban tabuľa, kde tím tvoria AI agenti. Každý projekt má vedúceho, ktorý plánuje prácu, a pomocníkov, ktorí ju stavajú. Keď je funkcia hotová, AI tester ju vyskúša a urobí snímku obrazovky, potom pristane na tvojej kôpke. Schváľ ju, alebo napíš komentár a prepracujú ju.","Začalo to ako spôsob, ako si jeden človek stráži veľa AI programátorských relácií naraz, a vyrástla z toho poriadna tabuľa. Beží na tvojom stroji, nepotrebuje účet a nemá sledovače. Pre priateľov a zvedavcov je zadarmo. Je aj nedokončená, takže počítaj s hranami a občasným prekvapením.","Tu je úprimná verzia. Nápady musíš stále mať ty a výsledky musíš stále skontrolovať ty. AI-gile robí všetko, čo je medzi tým: drží karty v poriadku, zobudí správneho agenta, keď napíšeš komentár, presne ukáže, čo sa zmenilo, a všetko ti zloží do jednej krátkej kôpky, ktorú zvládneš prejsť aj pri raňajšej káve."]},{"n":89,"texts":["AI-gile je bezplatná kanban tabuľa, ktorú spúšťaš na vlastnom počítači. Namiesto ľudí má každý projekt tím AI agentov: vedúceho, ktorý tvoje nápady premení na karty a plán, a pomocníkov, ktorí karty preberajú podľa priority. Keď je niečo postavené, AI tester prejde testovacie kroky a ukáže ti, čo videl. Potom to čaká v jednej kôpke s názvom Pre teba. Schválíš to, alebo napíšeš komentár a tím to skúsi znova. Do stĺpca Hotovo sa nič nedostane bez teba.","Niekoľko vecí, ktoré by ťa mohli prekvapiť. Nočná hliadka dopĺňa stĺpec Na urobenie, kým spíš, a vyberá karty, ktoré od teba nepotrebujú odpoveď. Počítadlo tokenov ukazuje, koľko agenti minuli dnes a tento týždeň, a Režim bez tokenov im povie, aby prestali míňať. S priateľmi si môžeš písať a súkromné správy sú šifrované end-to-end. Tabuľa hovorí približne 120 jazykmi, aj holandsky, flámsky, pirátsky a klingonsky. Nič z toho nestojí ani cent a nikto sa ti to ani nesnaží predať.","AI-gile je malý osobný projekt, nie firma. Rich chcel spravovať niekoľko AI programátorských projektov bez otvárania každej aplikácie, tak spolu s agentmi postavil tabuľu a potom na nej postavil zvyšok seba samej. Je v uzavretej pre-alfe, čo znamená, že pre hŕstku priateľov funguje, väčšinou. Nemá cenník, newsletter ani plán rastu. Beží na tvojom počítači, bez účtov a bez sledovačov. Ak ti to znie užitočne, môžeš si vyžiadať vyskúšanie, keď sa trochu viac otvorí. Napíšeme ti jediný e-mail, nič iné."]},{"n":144,"texts":["AI-gile je kanban tabuľa pre jedného človeka a veľa AI agentov. Beží na tvojom vlastnom počítači a je úplne zadarmo. Pridáš projekty a každý dostane vedúceho a malý tím. S vedúcim chatuješ, trochu ako na Discorde, a opíšeš nápad; vedúci z neho spraví karty a plán a potom čaká, kým stlačíš Ísť na to. Tím prechádza karty podľa priority pomocou jednoduchého príkazového riadku vytvoreného pre jazykové modely. Skôr než sa čokoľvek vráti k tebe, AI tester prejde kroky v kópii aplikácie a priloží snímku obrazovky. Hotová práca pristane na tvojej kôpke so zmenenými súbormi a rozdielmi. Schválíš ju, alebo zanecháš komentár a tím sa zobudí a skúsi to znova. Kartu do Hotovo môžeš presunúť len ty.","Deň s AI-gile, zhruba. Večer necháš pár komentárov: toto tlačidlo je na zlom mieste, ten zoznam by mal byť zoradený, mohli by sme mať tmavý režim. Ideš spať. Agenti si prečítajú komentáre, urobia zmeny, otestujú ich a vrátia ti ich. Ak Na urobenie vyschne, nočná hliadka ho doplní z backlogu kartami, ktoré od teba nepotrebujú odpoveď. Ráno je tu jedna krátka kôpka: pár otázok a zopár vecí na vyskúšanie, každá s krokmi, ktoré zvládne aj rozospatý človek, a so snímkou, že to funguje. Prekliknieš sa, schváliš dobré a zvyšok pošleš späť. Počítadlo tokenov ukáže, čo to všetko stálo, a Režim bez tokenov je tu na skromnejšie týždne. Potom si dáš raňajky, v ktorých ti agenti zatiaľ pomôcť nevedia.","Najprv to, čo AI-gile nie je. Nie je to startup, nie je na predaj a nikto nezbiera tvoje dáta. Je to bezplatná tabuľa, ktorá beží na tvojom počítači, bez účtov, bez sledovačov a bez cookies. A čo to je: jedno prehľadné miesto, kde vidíš všetky AI programátorské projekty naraz, s tímom agentov, ktorý robí karty, a tebou, ktorý rozhoduješ. Zlučuje súvisiace karty, opravuje zmätené názvy a pozerá, aby kód zostal štíhly. Hovorí približne 120 jazykmi, od holandčiny a flámčiny po pirátčinu a klingončinu. Priatelia si môžu písať súkromne a šifrovane. Postavil ho Rich s veľkým počtom trpezlivých agentov, väčšinou za pomoci seba samého. Je v uzavretej pre-alfe, takže miestami drhne. Ak ti to znie zábavne, pekne požiadaj a možno sa dostaneš dnu skôr."]}],"quips":{"1":"Jedno slovo. Odvážne. Možno príliš.","3":"Tri slová. Už teraz úprimnejšie ako väčšina produktových stránok.","8":"Osem slov. Stále kratšie ako stand-up.","21":"Dĺžky sú mimochodom story pointy. Samozrejme, že sú.","55":"Päťdesiatpäť slov. Kým si to čítal, dokončili sa dve karty.","144":"To je tá dlhá. 233 neexistuje. Agenti išli spať."}},"timeline":{"first-idea.name":"Prvý nápad","first-idea.line":"Úplne prvý rozhovor, ešte pred prvým riadkom kódu.","first-board.name":"Prvá tabuľa","first-board.line":"Tabuľa, ktorá sleduje vlastnú stavbu: karty, stĺpce, presúvanie, projekty.","team-roles.name":"Tím a roly","team-roles.line":"Profily agentov, šablóny tímov, priestory a kto robí čo.","install.name":"Inštalácia a vydania","install.line":"Zip, ktorý si nainštaluje aj kamarát, samoaktualizácie, kanály a návrat späť.","usage-saver.name":"Šetrič spotreby","usage-saver.line":"Zmeraj, koľko behy stoja, udržuj kód štíhly, šetri svoj limit.","friends.name":"Priatelia a zdieľanie","friends.line":"Súkromné správy, šifrované relé, pozvánky, roly a zdieľané projekty.","languages.name":"Jazyky","languages.line":"Každý text obrazovky v jazykovom súbore, najprv holandčina a flámčina.","ai-tester.name":"AI tester","ai-tester.line":"Tester najprv skontroluje každé odovzdanie a ukáže, čo videl.","website.name":"Web","website.line":"aigile.lol, ukážka a táto časová os.","streaming.name":"Chat a streamovanie","streaming.line":"Discord, Twitch, OBS, režim streamera, GIFy a emoji.","no-ai.name":"Edícia bez AI","no-ai.line":"Tabuľa pre ľudí, ktorí programujú bez AI, a verejné tabule.","night-watch.name":"Nočná hliadka","night-watch.line":"Strážca a Scrum Master držia tímy pri práci, kým spíš.","p-more.name":"Všetko ostatné","p-more.line":"Menšie nápady, ktoré čakajú na rad.","p-android.name":"Telefón a Android","p-android.line":"Tabuľa z telefónu a potom natívna aplikácia pre Android.","p-release.name":"Alfa a ďalej","p-release.line":"Uzavretá alfa, živý web a potom beta.","p-languages.name":"Viac jazykov","p-languages.line":"Viac než sto jazykov a imerzný režim pre študentov.","p-engines.name":"Viac AI motorov","p-engines.line":"Vyber Claude, Codex alebo Gemini pre každého agenta.","p-pro.name":"Profesionálna prax","p-pro.line":"Štítky rizika, brány zlúčenia, karty incidentov a zábradlia.","p-self.name":"Starostlivosť o teba","p-self.line":"Režim únavy, pripomienky starostlivosti o seba a 4:20.","p-servers.name":"Servery a rast","p-servers.line":"Globálne nastavenia servera, roly a plánovanie rastu.","p-livestream.name":"Streamovacie doplnky","p-livestream.line":"Twitch chat, vlastné emoji a verejný živý pohľad."},"words":{"button":"📖 Vývojárske slová","h":"📖 Vysvetlené slová","intro":"Slová, na ktoré v AI-gile narazíš, vysvetlené jednoducho: ako to postaviť, bezpečne meniť, udržať v chode pre ľudí, ktorí to používajú, a pracovať ako tím s AI.","search":"Hľadať slovo…","none":"Také slovo sa nenašlo.","close":"Zavrieť","count":{"one":"{count} word","other":"{count} words"},"groups":[{"id":"build","name":"🛠️ Ako to postaviť"},{"id":"change","name":"🔀 Bezpečné zmeny"},{"id":"run","name":"🛎️ Prevádzka služby"},{"id":"team","name":"🤝 Práca v tíme (aj s AI)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Priečinok projektu s kódom a celou históriou commitov, zvyčajne uložený aj na GitHube.","also":["repozitár","repozitára"]},{"id":"branch","g":"build","word":"Branch","text":"Samostatná línia práce v kóde, aby sa dali robiť zmeny bez dotyku hlavnej verzie.","also":["branche","vetva","vetvy"]},{"id":"commit","g":"build","word":"Commit","text":"Uložený snímok kódu s krátkou poznámkou o tom, čo sa zmenilo. Vždy sa k nemu dá vrátiť.","also":["commity","commitu","commitov"]},{"id":"push","g":"build","word":"Push","text":"Odoslanie uložených snímkov (commitov) z tohto počítača na GitHub, aby boli zálohované a zdieľané."},{"id":"merge","g":"build","word":"Merge","text":"Zlúčenie zmien z vetvy späť do hlavnej verzie."},{"id":"pr","g":"build","word":"Pull request","text":"Žiadosť o kontrolu a zlúčenie zmien z vetvy do hlavnej verzie.","also":["PR"]},{"id":"refactor","g":"build","word":"Refaktoring","text":"Upratovanie kódu bez zmeny toho, čo robí: menšie súbory, jasnejšie názvy, menej opakovania."},{"id":"bug","g":"build","word":"Bug","text":"Niečo, čo nefunguje tak, ako má.","also":["bugy","bugu"]},{"id":"test","g":"build","word":"Test","text":"Vyskúšanie hotovej práce, aby sa overilo, že robí, čo sa žiadalo, ešte než ju prijmeš.","also":["testy","testu","testovanie","testovať"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Skratka pre quality assurance, teda zabezpečenie kvality: automatické kontroly, ktoré bežia predtým, než niečo ide naživo. Keď je QA červené, niečo zlyhalo a naživo to nepôjde, kým sa to neopraví.","also":["kontrola kvality","kontroly kvality","zabezpečenie kvality"]},{"id":"deploy","g":"change","word":"Deploy","text":"Nasadenie novej verzie naživo, napríklad na server, kde ju ľudia používajú."},{"id":"release","g":"change","word":"Vydanie","text":"Pomenovaný balík hotovej práce, ktorý ide naživo naraz, s krátkymi poznámkami o tom, čo sa zmenilo. 🚀 Vydania napíšu poznámky z hotových kariet.","also":["vydania","release","releasy"]},{"id":"rollback","g":"change","word":"Vrátiť späť","text":"Návrat k poslednej verzii, ktorá fungovala, keď nová robí problémy. V AI-gile z toho vznikne kontrolný zoznam krokov na vrátenie, ktoré sú zapísané pri každej zmene.","also":["rollback","vrátenie späť","vrátené späť"]},{"id":"live","g":"change","word":"Naživo","text":"Skutočná verzia, ktorú ľudia používajú, na rozdiel od kópie na skúšanie. Vývojári tomu hovoria aj produkcia.","also":["produkcia","ostrá prevádzka","live"],"noTip":1},{"id":"change","g":"change","word":"Zmena","text":"Plánovaná zmena niečoho, na čo sa ľudia spoliehajú, najprv zapísaná: čo, prečo, riziko, kedy a ako ju vrátiť. Začni ju cez 🔀 Zadať zmenu.","also":["zmeny","žiadosť o zmenu","žiadosti o zmenu"],"noTip":1},{"id":"risk","g":"change","word":"Riziko","text":"Niečo, čo by sa mohlo pokaziť, ohodnotené podľa toho, aké je to pravdepodobné a aké zlé by to bolo. ⚠️ Riziká ich držia v jednom zozname, najvyššie skóre navrchu, každé s dátumom, kedy sa naň znova pozrieť.","also":["riziká","register rizík"]},{"id":"chgwin","g":"change","word":"Okno zmien","text":"Časy, kedy môžu zmeny ísť naživo, napríklad pokojný utorkový večer. Mimo okna sa karta zmeny nedá dokončiť, pokiaľ nejde o niečo naliehavé.","also":["okná zmien","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Rýchle hlasovanie tesne predtým, než zmena ide naživo: každý, kto ju musí schváliť, povie Go alebo No go. Pokračuje sa, len keď sa zhodnú.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Schválenie","text":"Čakanie na áno, kým sa práca začne. Karta, ktorú zadá priateľ, alebo zmena čaká v ✅ Schváleniach, kým ju neschváliš alebo neodmietneš.","also":["schválenia","schváliť"]},{"id":"quiettime","g":"change","word":"Tichý čas","text":"Úsek času, napríklad stream, demo alebo noc, keď nič nejde naživo. Tímy ďalej pracujú a testujú, ale nasadenie počká, kým sa neskončí. Inde sa tomu hovorí zmrazenie zmien.","also":["tiché časy","zmrazenie zmien","change freeze"]},{"id":"service","g":"run","word":"Služba","text":"Niečo, čo si postavil a na čo sa ľudia spoliehajú, napríklad web alebo aplikácia, o čo sa niekto stará, aby to stále fungovalo. Zaškrtni „Tento projekt je služba“ a napíš, čo ponúka, kto ju používa a kto má pohotovosť.","also":["služby","servis"]},{"id":"uptime","g":"run","word":"Kontrola dostupnosti","text":"Automatická kontrola každých pár minút, či tvoja služba ešte odpovedá. Ak niekoľkokrát za sebou zlyhá, AI-gile sám otvorí kartu incidentu.","also":["dostupnosť","uptime","kontroly dostupnosti"]},{"id":"statuspage","g":"run","word":"Stránka stavu","text":"Verejná stránka, ktorá ukazuje, či služba funguje (zelená, oranžová alebo červená), spolu s poslednou správou, aby si to ľudia, ktorí ju používajú, mohli pozrieť namiesto pýtania sa.","also":["stránky stavu","stavová stránka","status page"]},{"id":"incident","g":"run","word":"Incident","text":"Niečo, čo je práve teraz pokazené pre ľudí, ktorí to používajú, napríklad keď web nejde. Karta 🔥 incidentu predbieha rad: najprv treba, aby to znova fungovalo.","also":["incidenty","výpadok"]},{"id":"major","g":"run","word":"Závažný incident","text":"Veľký incident: zasiahnutých je veľa ľudí alebo sú v ohrození peniaze či dáta. Jedno tlačidlo naň postaví všetky tímy (roj), zobudí toho, kto má pohotovosť, a každých 30 minút si vypýta správu o stave.","also":["závažné incidenty","major incident"]},{"id":"oncall","g":"run","word":"Pohotovosť","text":"Byť ten, kto odpovedá, keď sa niečo pokazí, aj v noci. Každá služba má člena tímu s pohotovosťou, ktorého pri jej incidentoch zobudia ako prvého.","also":["pohotovostný","on call","on-call"]},{"id":"replyby","g":"run","word":"Termín odpovede","text":"Ako dlho môže karta čakať na prvú odpoveď, napríklad hodinu pri incidente. Potom dostane červené hodiny, aby sa nič potichu nezabudlo. Hovorí sa tomu aj cieľ odozvy.","also":["termíny odpovedí","cieľ odozvy","ciele odozvy"]},{"id":"postmortem","g":"run","word":"Rozbor incidentu","text":"Krátky pohľad späť po incidente: čo sa stalo, čo pomohlo a čo zmeniť, bez obviňovania kohokoľvek. Bez neho sa incident nedá zavrieť. Často sa mu hovorí aj post-mortem.","also":["rozbory incidentov","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Problém","text":"Skrytá príčina za jedným alebo viacerými incidentmi. Karta 🧩 problému spojí incidenty, ktoré sa stále vracajú, aby sa príčina našla a opravila nadobro.","also":["problémy"],"noTip":1},{"id":"rootcause","g":"run","word":"Príčina","text":"Skutočný dôvod, prečo sa niečo pokazilo, nie len to, čo si videl, že nejde. Oprav príčinu a incident sa prestane vracať.","also":["príčiny","koreňová príčina","root cause"]},{"id":"workaround","g":"run","word":"Náhradné riešenie","text":"Spôsob, ako udržať veci v chode, kým nie je hotová skutočná oprava, napríklad reštartovať niečo, keď sa to zasekne. Zapíše sa na kartu problému, aby to nikto nemusel vymýšľať znova.","also":["náhradné riešenia","workaround","obchádzka"]},{"id":"knownerror","g":"run","word":"Známa chyba","text":"Problém, ktorého príčina je jasná a má náhradné riešenie, ale ešte nie je opravený. 🧩 Známe chyby ich vypisujú, aby všetci použili náhradné riešenie namiesto ďalšieho pátrania.","also":["známe chyby","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Návod krok za krokom, ako opraviť známy druh problému, aby sa to zakaždým urobilo rovnako a rýchlo. Po veľkom incidente ti ho tím môže navrhnúť na odsúhlasenie.","also":["runbooky","postup","prevádzkový postup"]},{"id":"backup","g":"run","word":"Záloha","text":"Uložená kópia tvojich dát zo skoršia, na ktorú sa dá vrátiť, ak sa niečo stratí alebo poškodí. AI-gile robí zálohu tvojich boardov každý deň.","also":["zálohy","backup","zálohovanie"]},{"id":"restore","g":"run","word":"Obnovenie","text":"Vrátenie dát zo zálohy. Záloha naozaj platí, až keď vieš, že sa z nej dá obnoviť, takže sa oplatí to občas vyskúšať.","also":["obnoviť","obnovené","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Nápady a práca, ktoré ešte nie sú naplánované. Nič z toho sa nerobí, kým sa to nepresunie do stĺpca Na urobenie."},{"id":"sprint","g":"team","word":"Sprint","text":"Krátke obdobie práce (často týždeň či dva) s dohodnutou sadou kariet, ktoré treba dokončiť.","also":["sprinty","sprintov","sprintu"]},{"id":"standup","g":"team","word":"Stand-up","text":"Rýchle stretnutie: čo kto urobil, čo bude robiť ďalej a čo mu bráni.","also":["standup","stand-upy","stand-upu"]},{"id":"kanban","g":"team","word":"Kanban","text":"Board so stĺpcami (Na urobenie, Rozrobené, Hotovo), na ktorom sa karty presúvajú zľava doprava, ako práca pokračuje."},{"id":"wip","g":"team","word":"WIP limit","text":"Work in progress: maximálny počet kariet v stĺpci, aby tím veci dokončoval skôr, než začne ďalšie.","also":["WIP"]},{"id":"dod","g":"team","word":"Definícia Hotovo","text":"Krátky kontrolný zoznam tímu, čo znamená „hotové“, napríklad otestované a vysvetlené, predtým než ti karta príde. Jej dvojča, Definícia Pripravené, hovorí, kedy je karta dosť jasná na začatie.","also":["Definition of Done","Definícia Pripravené","Definition of Ready"]},{"id":"testpile","g":"team","word":"Balík testov","text":"Hotové karty, ktoré čakajú, kým ich vyskúšaš, jedna po druhej. Jednu prijmi alebo ju pošli späť s poznámkou a príde ďalšia.","also":["balíky testov","testovací balík"]},{"id":"retro","g":"team","word":"Retro","text":"Pohľad späť na to, ako tím pracuje, aby sa dohodol na jednej veci, ktorú robiť lepšie. V AI-gile retro navrhne zmenu v spôsobe práce tímu a ty povieš Do toho alebo Zatiaľ nie.","also":["retrá","retrospektíva","retrospektívy"]},{"id":"peerreview","g":"team","word":"Kontrola kolegami","text":"Druhý pár očí: iná AI skontroluje prácu na každej karte, skôr než sa dostane k tebe, aby prekĺzlo menej chýb.","also":["peer review","code review","revízia kódu"]},{"id":"swarm","g":"team","word":"Roj","text":"Všetci na palubu: každý tím odloží inú prácu a pomáha na jednom naliehavom projekte, kým sa to nevyrieši. Ostatné projekty medzitým čakajú.","also":["swarm","swarming","rojenie"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Ten, kto drží prácu v pohybe: všimne si zaseknuté karty, postrčí tímy a pripomenie ti, čo čaká. V AI-gile to Lead Scrum Master robí naprieč všetkými projektmi.","also":["Lead Scrum Master","hlavný Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI, ktorá pracuje na úlohe sama: číta kód, robí zmeny, spúšťa kontroly a hlási späť.","also":["agenti","agentov"]},{"id":"token","g":"team","word":"Token","text":"Jednotka, v ktorej sa počíta využitie AI: zhruba pár písmen prečítaného alebo napísaného textu. Čím menej tokenov, tým viac z plánu ostane.","also":["tokeny","tokenov"]},{"id":"hook","g":"team","word":"Hook","text":"Malý príkaz, ktorý sa sám spustí v určitom okamihu, napr. keď sa začne relácia AI, aby tím počul tvoje komentáre.","also":["hooky","hooku"]}]}};
